// BAD: parent pipelined, child loop remains
for (int i = 0; i < TILE; i++) {
#pragma HLS PIPELINE II=1
    for (int j = 0; j < N; j++) {  // child still exists
        A[i][j] = local_A[i][j];
    }
}
// GOOD: pipeline innermost only
for (int i = 0; i < TILE; i++) {
    for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        A[i][j] = local_A[i][j];
    }
}

// BAD: variable bound, tripcount pragma only
for (int k = 0; k < j; k++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=N
#pragma HLS PIPELINE II=1
    ...
}
// GOOD: fixed bound + guard
for (int k = 0; k < TILE_SIZE; k++) {
#pragma HLS PIPELINE II=1
    if (k < j) { ... }
}

// BEFORE: for (int k = 0; k < j; k++)
// AFTER:
for (int k = 0; k < TILE_SIZE; k++) {
#pragma HLS PIPELINE II=1
    if (k < j) {
        ...
    }
}

// BAD:
for (int k = 0; k < N; k++) {
#pragma HLS PIPELINE II=1
    w -= a[k] * b[k];
}
// GOOD: partial accumulators + final reduce (see hls-fp-reduction-partial-accumulators)

const int UF = 4;
double partial[UF];
#pragma HLS ARRAY_PARTITION variable=partial complete
for (int p = 0; p < UF; p++) {
#pragma HLS UNROLL
    partial[p] = 0.0;
}
for (int k = 0; k < TILE_SIZE; k += UF) {
#pragma HLS PIPELINE II=1
    for (int p = 0; p < UF; p++) {
#pragma HLS UNROLL
        if (k + p < j) partial[p] += expr(k + p);
    }
}
double sum = 0; for (int p = 0; p < UF; p++) { #pragma HLS UNROLL sum += partial[p]; }

// BAD (asks HLS to move whole row per cycle):
for (int i = 0; i < TILE_SIZE; i++) {
#pragma HLS PIPELINE II=1
    for (int j = 0; j < N; j++) A[i][j] = local_A[i][j];
    y[i] = local_y[i];
}
// GOOD:
for (int i = 0; i < TILE_SIZE; i++) {
    for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        A[i][j] = local_A[i][j];
    }
    y[i] = local_y[i];
}

load_tile: for (int i = 0; i < TILE_SIZE; i++) {
    for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        local_A[i][j] = A[tile_i + i][j];
    }
    local_b[i] = b[tile_i + i];
}
store_tile: for (int i = 0; i < TILE_SIZE; i++) {
    for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        A[tile_i + i][j] = local_A[i][j];
    }
    y[tile_i + i] = local_y[i];
}

const int UF = 4;
data_t buf[N];
#pragma HLS ARRAY_PARTITION variable=buf cyclic factor=UF dim=1
data_t partial[UF];
#pragma HLS ARRAY_PARTITION variable=partial complete

// GOOD canonical DATAFLOW:
#pragma HLS DATAFLOW
hls::stream<tile_t> load_to_compute;
load_tile(A, load_to_compute, tile_i);
compute_tile(load_to_compute, compute_to_store);
store_tile(compute_to_store, A, tile_i);

// BAD:
for (int tile_i = 0; tile_i < N; tile_i += TILE_SIZE) {
#pragma HLS DATAFLOW
    ...
}
// GOOD:
for (int tile = 0; tile < NUM_TILES; tile++) {
    const int tile_i = tile * TILE_SIZE;
    process_tile_lcs(A, b, y, tile_i);  // helper contains DATAFLOW + 3 calls
}

// BAD: fake ping-pong — still serial per tile
for (int tile = 0; tile < NUM_TILES; tile++) {
    load_tile(A, buf[tile & 1], tile);
    compute_tile(buf[tile & 1], out_buf[tile & 1]);
    store_tile(out_buf[tile & 1], A, tile);
}
// GOOD without overlap: single local buffer + pipelined loops
// GOOD with overlap: DATAFLOW helper where load(t+1) || compute(t) || store(t-1)

// Triangular/pivot-dependent tiles often depend on prior rows/columns
// BAD: ping-pong across tiles without dependence proof
// GOOD: sequential tiles; optional DATAFLOW only inside one tile:
void process_tile_lcs(...) {
#pragma HLS DATAFLOW
    load_tile(...);
    compute_tile(...);
    store_tile(...);
}

void process_tile_lcs(...) {
#pragma HLS DATAFLOW
    tile_buf_t stage_buf;
    load_tile(A, b, stage_buf, tile_i);
    compute_tile(stage_buf, tile_i);
    store_tile(stage_buf, A, y, tile_i);
}

for (int tile = 0; tile < NUM_TILES; tile++) {
    process_tile_lcs(A, b, y, tile * TILE_SIZE);
}

// BAD: RMW on local output inside pipelined unroll
for (int k = 0; k < UF; k++) {
#pragma HLS UNROLL
#pragma HLS PIPELINE II=1
    local_x[i] += A[i][j + k] * y[j + k];
}
// GOOD: partial accumulators, single write
partial[p] += A[i][j+p] * y[j+p];  // in pipelined loop
local_x[i] = reduce(partial);        // once after loop

const int UF = 4;
data_t A_local[N][N];
data_t y_local[N];
#pragma HLS ARRAY_PARTITION variable=A_local cyclic factor=UF dim=2
#pragma HLS ARRAY_PARTITION variable=y_local cyclic factor=UF dim=1

for (int k = 0; k < UF; k++) {
#pragma HLS UNROLL
    partial[k] += A_local[i][j + k] * y_local[j + k];
}

load_matrix_dual: for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        data_t v = A[i][j];           // one m_axi read
        local_A[i][j] = v;
        local_AT[j][i] = v;           // transpose view from same read
    }
}
// compute uses local_A / local_AT — no second full-matrix m_axi traversal

// FORBIDDEN when A/x/w are m_axi ports:
//   A[i][j] = A[i][j] + expr;
//   x[i] = x[i] + expr;
// GOOD: load -> local acc/buffer -> single store
//   double acc = x_local[i];
//   for (int j = 0; j < N; j++) acc += beta * A_local[j][i] * y_local[j];
//   x_local[i] = acc;
//   x[i] = x_local[i];  // one write per element

load_phase: copy inputs from m_axi ports into local buffers (pipelined).
compute_phase: update locals/scalar accumulators only.
store_phase: write finalized locals back to m_axi outputs once.
// Reduction example:
//   double acc = x_local[i];
//   for (int j = 0; j < N; j++) acc += beta * A_local[j][i] * y_local[j];
//   x_local[i] = acc;
//   x[i] = x_local[i];

OVERLAP REPORT (required if DATAFLOW kept):
| stage pairing | overlap? | evidence (stream / gmemN / schedule) |

// BAD: tasks share locals only, one gmem bundle
#pragma HLS DATAFLOW
load_all(...);   // writes shared local_A
compute_all(...); // reads same local_A — no stream, no overlap proof

// GOOD: streams between tasks OR distinct gmemN + proven concurrent schedule
#pragma HLS DATAFLOW
hls::stream<tile_t> q;
load_tile(A, q, tile_i);
compute_tile(q, out_q);
store_tile(out_q, y, tile_i);

// BAD: stacked outer-pipelined row loops in one task
void load_all(...) {
    for (int i = 0; i < TILE_SIZE; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) local_A[i][j] = A[...][j];
    }
    for (int i = 0; i < TILE_SIZE; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) local_B[i][j] = B[...][j];
    }
}
// GOOD: innermost pipeline per matrix or flat fused index
for (int i = 0; i < TILE_SIZE; i++) {
    for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        local_A[i][j] = A[tile_i + i][j];
    }
}

// BAD: three full local matrices + copy tasks between DATAFLOW stages
local_T1[N][N]; local_T2[N][N]; local_T3[N][N];
#pragma HLS DATAFLOW
load_AB(...); gemm1_copy(...); gemm2_copy(...); store_C(...);

// GOOD: K-panel reuse, innermost K pipelined
for (int k = 0; k < N; k++) {
#pragma HLS PIPELINE II=1
    for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS UNROLL factor=UF
        acc[j] += A[i][k] * B[k][j];
    }
}
// optional: hls::stream<panel_t> between stages when overlap proven

// BAD: runtime tile_size as pipelined loop bound
int tile_size = (tile_i + TILE_SIZE > N) ? (N - tile_i) : TILE_SIZE;
for (int i = 0; i < tile_size; i++) {
#pragma HLS PIPELINE II=1
    local_A[i][j] = A[tile_i + i][j];
}

// GOOD: fixed TILE_SIZE bound + guard
for (int i = 0; i < TILE_SIZE; i++) {
#pragma HLS PIPELINE II=1
    if (tile_i + i < N) {
        local_A[i][j] = A[tile_i + i][j];
    }
}

// BAD: per-tile m_axi RMW on output vector
for (int tile = 0; tile < NUM_TILES; tile++) {
    for (int i = 0; i < TILE_SIZE; i++) {
        local_x[i] = x[tile_i + i];      // m_axi read
        ... local_x[i] += contrib ...
        x[tile_i + i] = local_x[i];        // m_axi write same element
    }
}

// GOOD: local accumulate, single store pass
load_x_to_local(x, local_x);           // once or per region
tiled_compute_accumulate(local_x, ...);
store_x_from_local(x, local_x);         // one write per element

// BAD: one writer, two readers on local_tmp
#pragma HLS DATAFLOW
compute_tmp(..., local_tmp);
compute_next(..., local_tmp);  // reader 1
store_tmp(..., local_tmp);     // reader 2 — HLS 200-779

// GOOD: linear chain or stream fan-out
hls::stream<tile_t, DEPTH> q;
compute_tmp(..., q);
compute_next(q, local_out);
store_tmp(..., local_out);

// BAD: t-loop inside DATAFLOW with alternating writers on local_A
#pragma HLS DATAFLOW
load(...);
for (int t = 0; t < TSTEPS; t++) {
    compute_B(local_A, local_B);
    compute_A(local_B, local_A);  // HLS 200-979
}
store(...);

// GOOD: one compute task owns the t-loop
#pragma HLS DATAFLOW
load(..., local_A);
compute_timesteps(local_A, local_B, local_A_new);
store(..., local_B);

// BAD: tile loop inside DATAFLOW — parallel A readers
#pragma HLS DATAFLOW
for (int i0 = 0; i0 < N; i0 += TILE_SIZE) {
    load_tile_A(A, local_A, i0);  // HLS 200-1013 on gmem for A
    compute_tile(...);
}

// GOOD: fused load once, or stream pipeline
#pragma HLS DATAFLOW
fused_load_all_inputs(...);   // single reader per port
compute_all_tiles(...);       // locals only
fused_store_all_outputs(...);

#pragma HLS ARRAY_PARTITION variable=local_A cyclic factor=UF dim=2
#pragma HLS DATAFLOW
load_A_task(...);   // gmem0
load_B_task(...);   // gmem1 — parallel with load_A
compute_tile_task(...);
store_C_task(...);

// inside compute:
for (int j = 0; j < N; j += UF) {
#pragma HLS PIPELINE II=1
    for (int k = 0; k < UF; k++) {
#pragma HLS UNROLL
        acc += local_A[i][j+k] * local_B[j+k][l];
    }
}

// BAD: two readers on local_A and local_tmp
#pragma HLS DATAFLOW
compute_tmp(..., local_A, local_tmp);
compute_y(..., local_A, local_tmp);   // local_A reader 2, local_tmp reader 2
store_tmp(..., local_tmp);

// GOOD: fused compute, parallel load/store
#pragma HLS DATAFLOW
load_A_task(...); load_x_task(...);
compute_fused_task(local_A, local_x, local_tmp, local_y);  // both matvecs inside
store_y_task(...); store_tmp_task(...);

// BAD: tile loops inside DATAFLOW reload A each tile
#pragma HLS DATAFLOW
for (i0 = 0; i0 < N; i0 += TILE) {
    load_tile_A(A, local_A, i0);  // HLS 200-1013
    compute_tile(...);
}

// GOOD: fused dual-layout load, phased compute on locals
#pragma HLS DATAFLOW
fused_load_task(y1, y2, A, local_y1, local_y2, local_A_row, local_A_col);
phase1_task(local_x1, local_A_row, local_y1);
phase2_task(local_x2, local_A_col, local_y2);
fused_store_task(x1, x2, local_x1, local_x2);

// BAD: local_A_out read by two compute tasks
#pragma HLS DATAFLOW
compute_A_task(..., local_A_out);
compute_x_task(local_A_out, ...);  // reader 1
compute_w_task(local_A_out, ...);  // reader 2 — HLS 200-779

// GOOD: merge consumers
#pragma HLS DATAFLOW
compute_A_task(..., local_A_out);
compute_xw_task(local_A_out, local_x, local_w, ...);  // both uses inside one task
store_x_task(...); store_w_task(...);
